import { useReducer } from "react";

const UseReducerHook = () => {
 const initialStateValue = {
   count: 0,
   showCountFlag: true,
 };

 const reducerFunc = (initialValue, action) => {
   switch (action.type) {
     case "add":
       return { ...initialValue, count: initialValue.count + 1};
     case "subtract":
       return { ...initialValue, count: initialValue.count - 1 };
     case "reset":
       return { ...initialValue, count: 0 };
     case "show_hide":
       return { ...initialValue, showCountFlag: !initialValue.showCountFlag };
     default:
       return initialValue;
   }
 };

 const [state, dispatch] = useReducer(reducerFunc, initialStateValue);

 return (
   <div>
     <h1>use Reducer Hook</h1>
     {state.showCountFlag ? <h3>Count is {state.count}</h3> : null}
     <button onClick={() => dispatch({ type: "add" })}>
       Increase Count
     </button>
     <button onClick={() => dispatch({ type: "subtract" })}>
       Decrease Count
     </button>
     <button onClick={() => dispatch({ type: "reset" })}>Reset</button>
     <button onClick={() => dispatch({ type: "show_hide" })}>
       Show / Hide
     </button>
   </div>
 );
};

export default UseReducerHook;

